import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose3d_forward(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride, int64_t padding, int64_t output_padding,
    int64_t dilation, int64_t groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <type_traits>

using namespace cute;

template <typename T, int OC_TILE>
__global__ void __launch_bounds__(256, 5) conv_transpose3d_kernel(
    const T* __restrict__ Xp,
    const T* __restrict__ Wp,
    const T* __restrict__ Bp,
    T* __restrict__ Yp,
    int N, int Cin, int D, int H, int W,
    int Cout, int K,
    int stride, int padding, int dilation,
    int groups,
    int Dout, int Hout, int Wout,
    int Cin_per_group, int Cout_per_group)
{
  constexpr int Threads = 256;
  constexpr int CIN_TILE = 16;
  constexpr int WTILE = 2;
  const int tid = threadIdx.x;
  const int n       = blockIdx.z;
  const int oc_tile = blockIdx.y;
  const int oc_base = oc_tile * OC_TILE;
  const int group_id          = oc_base / Cout_per_group;
  const int ic_base           = group_id * Cin_per_group;
  const int oc_in_group_base  = oc_base - group_id * Cout_per_group;
  const int P_total = Dout * Hout * Wout;
  const int p0 = (blockIdx.x * Threads + tid) * WTILE;
  const int K2  = K * K;
  const int KKK = K * K * K;
  // Global tensors (this batch n) using CuTe
  const int64_t sXc = (int64_t)D * H * W;
  const int64_t sXh = (int64_t)H * W;
  const int64_t sXw = (int64_t)W;
  const int64_t sYc = (int64_t)Dout * Hout * Wout;
  const int64_t sYh = (int64_t)Hout * Wout;
  const int64_t sYw = (int64_t)Wout;
  Tensor mX = make_tensor(
      make_gmem_ptr(Xp + (int64_t)n * Cin * sXc),
      make_shape(Cin, D, H, W),
      make_stride(sXc, sXh, sXw, (int64_t)1));
  Tensor mY = make_tensor(
      make_gmem_ptr(Yp + (int64_t)n * Cout * sYc),
      make_shape(Cout, Dout, Hout, Wout),
      make_stride(sYc, sYh, sYw, (int64_t)1));
  Tensor mW = make_tensor(
      make_gmem_ptr(Wp),
      make_shape(Cin, Cout_per_group, K, K, K),
      make_stride((int64_t)Cout_per_group * KKK, (int64_t)KKK, (int64_t)K2, (int64_t)K, (int64_t)1));
  extern __shared__ unsigned char smem_raw[];
  T* smem = reinterpret_cast<T*>(smem_raw);
  // Shared-memory tile only covers a CIN_TILE-sized chunk of Cin_per_group at a time.
  // This drastically reduces per-block dynamic shared memory usage, allowing more
  // concurrent blocks per SM (higher occupancy) while still reusing weights across
  // all output positions handled by the block for each chunk.
  Tensor sW = make_tensor(
      make_smem_ptr(smem),
      make_shape(Int<OC_TILE>{}, CIN_TILE, KKK),
      make_stride(CIN_TILE * KKK, KKK, 1));
  int od[WTILE], oh[WTILE], ow[WTILE];
  bool active[WTILE];
  bool any_active = false;
#pragma unroll
  for (int i = 0; i < WTILE; ++i) {
    int p = p0 + i;
    active[i] = (p < P_total);
    if (active[i]) {
      od[i] = p / (Hout * Wout);
      int rem = p - od[i] * Hout * Wout;
      oh[i] = rem / Wout;
      ow[i] = rem - oh[i] * Wout;
      any_active = true;
    } else {
      od[i] = 0; oh[i] = 0; ow[i] = 0;
    }
  }
  float acc[OC_TILE][WTILE];
#pragma unroll
  for (int occ = 0; occ < OC_TILE; ++occ) {
#pragma unroll
    for (int i = 0; i < WTILE; ++i) acc[occ][i] = 0.0f;
  }
  const int num_chunks = (Cin_per_group + CIN_TILE - 1) / CIN_TILE;
  for (int c = 0; c < num_chunks; ++c) {
    const int ic_chunk_base = c * CIN_TILE;
    // Cooperative load of the weight chunk into shared memory
    const int total_w = OC_TILE * CIN_TILE * KKK;
    for (int idx = tid; idx < total_w; idx += Threads) {
      int kk       = idx % KKK;
      int t2       = idx / KKK;
      int ic_local = t2 % CIN_TILE;
      int occ      = t2 / CIN_TILE;
      int oc       = oc_base + occ;
      int ic       = ic_chunk_base + ic_local;
      T val = T(0);
      if (oc < Cout && ic < Cin_per_group) {
        int ic_global   = ic_base + ic;
        int oc_in_group = oc_in_group_base + occ;
        int kd = kk / K2;
        int r2 = kk % K2;
        int kh = r2 / K;
        int kw = r2 % K;
        val = mW(ic_global, oc_in_group, kd, kh, kw);
      }
      sW(occ, ic_local, kk) = val;
    }
    __syncthreads();
    if (any_active) {
      for (int kd = 0; kd < K; ++kd) {
        int id[WTILE]; bool dvalid[WTILE]; bool any_d = false;
#pragma unroll
        for (int i = 0; i < WTILE; ++i) {
          if (active[i]) {
            int id_num = od[i] + padding - kd * dilation;
            bool ok = (id_num % stride == 0);
            int idv = id_num / stride;
            ok = ok && (idv >= 0 && idv < D);
            id[i] = idv;
            dvalid[i] = ok;
            any_d = any_d || ok;
          } else {
            id[i] = 0; dvalid[i] = false;
          }
        }
        if (!any_d) continue;
        for (int kh = 0; kh < K; ++kh) {
          int ih[WTILE]; bool hvalid[WTILE]; bool any_h = false;
#pragma unroll
          for (int i = 0; i < WTILE; ++i) {
            if (dvalid[i]) {
              int ih_num = oh[i] + padding - kh * dilation;
              bool ok = (ih_num % stride == 0);
              int ihv = ih_num / stride;
              ok = ok && (ihv >= 0 && ihv < H);
              ih[i] = ihv;
              hvalid[i] = ok;
              any_h = any_h || ok;
            } else {
              ih[i] = 0; hvalid[i] = false;
            }
          }
          if (!any_h) continue;
          for (int kw = 0; kw < K; ++kw) {
            int iw[WTILE]; bool valid[WTILE]; bool any_w = false;
#pragma unroll
            for (int i = 0; i < WTILE; ++i) {
              if (hvalid[i]) {
                int iw_num = ow[i] + padding - kw * dilation;
                bool ok = (iw_num % stride == 0);
                int iwv = iw_num / stride;
                ok = ok && (iwv >= 0 && iwv < W);
                iw[i] = iwv;
                valid[i] = ok;
                any_w = any_w || ok;
              } else {
                iw[i] = 0; valid[i] = false;
              }
            }
            if (!any_w) continue;
            const int kk = (kd * K + kh) * K + kw;
            const int ic_end = min(CIN_TILE, Cin_per_group - ic_chunk_base);
            for (int ic_local = 0; ic_local < ic_end; ++ic_local) {
              int ic_global = ic_base + ic_chunk_base + ic_local;
              float xval[WTILE];
#pragma unroll
              for (int i = 0; i < WTILE; ++i) {
                xval[i] = valid[i] ? (float)mX(ic_global, id[i], ih[i], iw[i]) : 0.0f;
              }
#pragma unroll
              for (int occ = 0; occ < OC_TILE; ++occ) {
                float wval = (float)sW(occ, ic_local, kk);
#pragma unroll
                for (int i = 0; i < WTILE; ++i) {
                  acc[occ][i] += xval[i] * wval;
                }
              }
            }
          }
        }
      }
    }
    __syncthreads();
  }
  if (!any_active) return;
#pragma unroll
  for (int i = 0; i < WTILE; ++i) {
    if (!active[i]) continue;
#pragma unroll
    for (int occ = 0; occ < OC_TILE; ++occ) {
      int oc = oc_base + occ;
      if (oc >= Cout) continue;
      float bval = Bp ? (float)Bp[oc] : 0.0f;
      mY(oc, od[i], oh[i], ow[i]) = (T)(acc[occ][i] + bval);
    }
  }
}

torch::Tensor conv_transpose3d_forward(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride, int64_t padding, int64_t output_padding,
    int64_t dilation, int64_t groups)
{
  TORCH_CHECK(x.is_cuda() && weight.is_cuda(), "x and weight must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat && weight.scalar_type() == at::kFloat,
              "Only float32 supported");
  TORCH_CHECK(x.dim() == 5, "x must be [N, Cin, D, H, W]");
  TORCH_CHECK(weight.dim() == 5, "weight must be [Cin, Cout/groups, K, K, K]");

  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();

  int N   = (int)x_c.size(0);
  int Cin = (int)x_c.size(1);
  int D   = (int)x_c.size(2);
  int H   = (int)x_c.size(3);
  int W   = (int)x_c.size(4);

  int Cout_per_group = (int)w_c.size(1);
  int K  = (int)w_c.size(2);
  TORCH_CHECK((int)w_c.size(3) == K && (int)w_c.size(4) == K, "kernel must be cubic");
  TORCH_CHECK((int)w_c.size(0) == Cin, "weight.size(0) must equal Cin");

  int Cout = Cout_per_group * (int)groups;
  TORCH_CHECK(Cin % groups == 0, "Cin must be divisible by groups");
  int Cin_per_group = Cin / (int)groups;

  int s  = (int)stride;
  int pd = (int)padding;
  int op = (int)output_padding;
  int dl = (int)dilation;

  int Dout = (D - 1) * s - 2 * pd + dl * (K - 1) + op + 1;
  int Hout = (H - 1) * s - 2 * pd + dl * (K - 1) + op + 1;
  int Wout = (W - 1) * s - 2 * pd + dl * (K - 1) + op + 1;
  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "invalid computed output size");

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (bias.has_value()) {
    b_c = bias.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && (int)b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x.options());

  int oc_tile = 1;
  {
    const int cands[4] = {8, 4, 2, 1};
    for (int i = 0; i < 4; ++i) {
      if (Cout_per_group % cands[i] == 0) { oc_tile = cands[i]; break; }
    }
  }

  constexpr int Threads = 256;
  constexpr int WTILE = 2;
  int P_total = Dout * Hout * Wout;
  dim3 block(Threads);
  dim3 grid((unsigned)((P_total + Threads * WTILE - 1) / (Threads * WTILE)),
            (unsigned)((Cout + oc_tile - 1) / oc_tile),
            (unsigned)N);

  size_t KKK = (size_t)K * K * K;
  constexpr size_t CIN_TILE = 16;
  size_t smem_bytes = (size_t)oc_tile * CIN_TILE * KKK * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  auto do_launch = [&](auto oct_const) {
    constexpr int OCT = decltype(oct_const)::value;
    cudaFuncSetAttribute((const void*)conv_transpose3d_kernel<float, OCT>,
                          cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_bytes);
    conv_transpose3d_kernel<float, OCT><<<grid, block, smem_bytes, stream>>>(
        x_c.data_ptr<float>(), w_c.data_ptr<float>(), b_ptr, y.data_ptr<float>(),
        N, Cin, D, H, W, Cout, K, s, pd, dl,
        (int)groups, Dout, Hout, Wout, Cin_per_group, Cout_per_group);
  };

  switch (oc_tile) {
    case 8: do_launch(std::integral_constant<int, 8>{}); break;
    case 4: do_launch(std::integral_constant<int, 4>{}); break;
    case 2: do_launch(std::integral_constant<int, 2>{}); break;
    default: do_launch(std::integral_constant<int, 1>{}); break;
  }

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv_transpose3d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv_transpose3d_ext = load_inline(
    name="cute_conv_transpose3d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv_transpose3d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Transposed 3D convolution with a cubic kernel, implemented with a single
    custom CUDA kernel using CuTe tensors for indexing.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.output_padding = int(output_padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        assert in_channels % groups == 0, "in_channels must be divisible by groups"
        assert out_channels % groups == 0, "out_channels must be divisible by groups"

        weight_shape = (self.in_channels, self.out_channels // self.groups,
                         self.kernel_size, self.kernel_size, self.kernel_size)
        self.weight = nn.Parameter(torch.empty(*weight_shape))

        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()
        self._ext = conv_transpose3d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = (self.in_channels // self.groups) * (self.kernel_size ** 3)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv_transpose3d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride), int(self.padding), int(self.output_padding),
            int(self.dilation), int(self.groups),
        )

